package br.edu.insper.transacoes; import java.math.BigDecimal; import java.time.LocalDateTime; public record TransactionResponse(Long id,Long clientId,String clientEmail,String stockCode,Integer quantity,BigDecimal unitPrice,BigDecimal totalValue,LocalDateTime transactedAt){static TransactionResponse from(Transaction t){return new TransactionResponse(t.getId(),t.getClientId(),t.getClientEmail(),t.getStockCode(),t.getQuantity(),t.getUnitPrice(),t.getTotalValue(),t.getTransactedAt());}}
